Here is the commit message:
libbpf: fix u64-to-pointer cast on 32-bit arches

It's been reported that (void *)map->map_extra is causing compilation
warnings on 32-bit architectures. It's easy enough to fix this by
casting to long first.

Fixes: 79ff13e99169 ("libbpf: Add support for bpf_arena.")
Reported-by: Ryan Eatmon <reatmon@ti.com>
Signed-off-by: Andrii Nakryiko <andrii@kernel.org>
Message-ID: <20240319215143.1279312-1-andrii@kernel.org>
Signed-off-by: Alexei Starovoitov <ast@kernel.org>

Here is the root cause:
The bug arises from an improper cast of a 64-bit value (`map->map_extra`) to a pointer type on 32-bit architectures, which can lead to compilation warnings and potential runtime issues due to differences in pointer size and integer size on these architectures. The fix involves casting the value to a `long` first, ensuring that the conversion is safe and compatible with the pointer type.

Here is the patch:

 static int
 bpf_object__create_maps(struct bpf_object *obj)
 {
 	struct bpf_map *map;
 	char *cp, errmsg[STRERR_BUFSIZE];
 	unsigned int i, j;
 	int err;
 	bool retried;

 	for (i = 0; i < obj->nr_maps; i++) {
 		map = &obj->maps[i];

 		/* To support old kernels, we skip creating global data maps
 		 * (.rodata, .data, .kconfig, etc); later on, during program
 		 * loading, if we detect that at least one of the to-be-loaded
 		 * programs is referencing any global data map, we'll error
 		 * out with program name and relocation index logged.
 		 * This approach allows to accommodate Clang emitting
 		 * unnecessary .rodata.str1.1 sections for string literals,
 		 * but also it allows to have CO-RE applications that use
 		 * global variables in some of BPF programs, but not others.
 		 * If those global variable-using programs are not loaded at
 		 * runtime due to bpf_program__set_autoload(prog, false),
 		 * bpf_object loading will succeed just fine even on old
 		 * kernels.
 		 */
 		if (bpf_map__is_internal(map) && !kernel_supports(obj, FEAT_GLOBAL_DATA))
 			map->autocreate = false;

 		if (!map->autocreate) {
 			pr_debug("map '%s': skipped auto-creating...\n", map->name);
 			continue;
 		}

 		err = map_set_def_max_entries(map);
 		if (err)
 			goto err_out;

 		retried = false;
 retry:
 		if (map->pin_path) {
 			err = bpf_object__reuse_map(map);
 			if (err) {
 				pr_warn("map '%s': error reusing pinned map\n",
 					map->name);
 				goto err_out;
 			}
 			if (retried && map->fd < 0) {
 				pr_warn("map '%s': cannot find pinned map\n",
 					map->name);
 				err = -ENOENT;
 				goto err_out;
 			}
 		}

 		if (map->reused) {
 			pr_debug("map '%s': skipping creation (preset fd=%d)\n",
 				 map->name, map->fd);
 		} else {
 			err = bpf_object__create_map(obj, map, false);
 			if (err)
 				goto err_out;

 			pr_debug("map '%s': created successfully, fd=%d\n",
 				 map->name, map->fd);

 			if (bpf_map__is_internal(map)) {
 				err = bpf_object__populate_internal_map(obj, map);
 				if (err < 0)
 					goto err_out;
 			}
 			if (map->def.type == BPF_MAP_TYPE_ARENA) {
-				map->mmaped = mmap((void *)map->map_extra, bpf_map_mmap_sz(map),
-						   PROT_READ | PROT_WRITE,
+				map->mmaped = mmap((void *)(long)map->map_extra,
+						   bpf_map_mmap_sz(map), PROT_READ | PROT_WRITE,
 						   map->map_extra ? MAP_SHARED | MAP_FIXED : MAP_SHARED,
 						   map->fd, 0);
 				if (map->mmaped == MAP_FAILED) {
 					err = -errno;
 					map->mmaped = NULL;
 					pr_warn("map '%s': failed to mmap arena: %d\n",
 						map->name, err);
 					return err;
 				}
 				if (obj->arena_data) {
 					memcpy(map->mmaped, obj->arena_data, obj->arena_data_sz);
 					zfree(&obj->arena_data);
 				}
 			}
 			if (map->init_slots_sz && map->def.type != BPF_MAP_TYPE_PROG_ARRAY) {
 				err = init_map_in_map_slots(obj, map);
 				if (err < 0)
 					goto err_out;
 			}
 		}

 		if (map->pin_path && !map->pinned) {
 			err = bpf_map__pin(map, NULL);
 			if (err) {
 				if (!retried && err == -EEXIST) {
 					retried = true;
 					goto retry;
 				}
 				pr_warn("map '%s': failed to auto-pin at '%s': %d\n",
 					map->name, map->pin_path, err);
 				goto err_out;
 			}
 		}
 	}

 	return 0;

 err_out:
 	cp = libbpf_strerror_r(err, errmsg, sizeof(errmsg));
 	pr_warn("map '%s': failed to create: %s(%d)\n", map->name, cp, err);
 	pr_perm_msg(err);
 	for (j = 0; j < i; j++)
 		zclose(obj->maps[j].fd);
 	return err;
 }



